const PREVIEW_BASE = "https://n8n.salmanpro.me/webhook/cfffa3a6-4149-43b4-9ba4-54dbd91e4ab5/preview/";
const raw = String($input.first().json.output || "");
let html = raw.trim();
const tick = String.fromCharCode(96);
const fence = tick + tick + tick;
const fs = html.indexOf(fence);
if (fs !== -1) {
  const after = html.slice(fs + 3);
  const nl = after.indexOf("\n");
  const body = nl === -1 ? after : after.slice(nl + 1);
  const fe = body.indexOf(fence);
  html = (fe === -1 ? body : body.slice(0, fe)).trim();
}
const dt = html.toLowerCase().indexOf("<!doctype");
if (dt > 0) { html = html.slice(dt); }
if (!html) { throw new Error("Builder Agent returned no HTML."); }
const ctx = $("Build Context").first().json;
return [{ json: { siteId: ctx.siteId, sessionId: ctx.sessionId, businessName: ctx.businessName, subdomainSlug: ctx.subdomainSlug, version: ctx.version, brief_object: ctx.brief_object, html: html, previewUrl: PREVIEW_BASE + ctx.siteId } }];

const PUBLISH_BASE = "https://n8n.salmanpro.me/webhook/c98e0946-402a-421b-943d-62866bcdbdd2/publish/";
const row = $input.first().json || {};
const siteId = $("Preview Webhook").first().json.params.siteId;
if (!row.html) {
  return [{ json: { html: "<!doctype html><html><head><meta charset=\"utf-8\"><title>Preview not found</title></head><body style=\"font-family:system-ui;padding:48px;text-align:center\"><h1>Preview not found</h1><p>No generated site matches <code>" + siteId + "</code>.</p></body></html>" } }];
}
const endpoint = PUBLISH_BASE + siteId;
const deployed = String(row.status) === "deployed";
const liveUrl = row.liveUrl ? String(row.liveUrl) : ("https://" + row.subdomainSlug + ".dripranks.com");
const btnLabel = deployed ? "Update Website" : "Publish Live";
const btnColor = deployed ? "#2563eb" : "#22c55e";
const btnText = deployed ? "#eff6ff" : "#052e16";
const liveLink = deployed ? ("<a href=\"" + liveUrl + "\" target=\"_blank\" rel=\"noopener\" style=\"color:#93c5fd;font-size:13px;text-decoration:underline\">View live ↗</a>") : "";
const bar = "<div style=\"position:fixed;left:0;right:0;bottom:0;z-index:2147483647;background:#0f172a;color:#fff;font-family:system-ui,-apple-system,sans-serif;padding:12px 18px;display:flex;gap:16px;align-items:center;justify-content:space-between;box-shadow:0 -2px 16px rgba(0,0,0,.35)\"><span style=\"font-size:14px\">Preview - v" + row.version + " - " + row.businessName + "</span><span style=\"display:flex;gap:14px;align-items:center\">" + liveLink + "<button id=\"n8nPublishBtn\" style=\"background:" + btnColor + ";color:" + btnText + ";border:0;border-radius:8px;padding:10px 20px;font-weight:700;font-size:14px;cursor:pointer\">" + btnLabel + "</button></span></div>" + "<script>(function(){var b=document.getElementById(\"n8nPublishBtn\");b.addEventListener(\"click\",function(){b.disabled=true;b.textContent=\"Publishing...\";fetch(\"" + endpoint + "\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:\"{}\"}).then(function(r){return r.json();}).then(function(d){b.textContent=(d&&d.message)?d.message:\"Live\";b.style.background=\"#2563eb\";b.style.color=\"#eff6ff\";setTimeout(function(){location.reload();},1400);}).catch(function(){b.textContent=\"Failed - retry\";b.disabled=false;});});})();<\/script>";
let html = String(row.html);
const idx = html.toLowerCase().lastIndexOf("</body>");
html = idx === -1 ? html + bar : html.slice(0, idx) + bar + html.slice(idx);
return [{ json: { html: html, siteId: siteId } }];

